 step(3, '✅ ר׳ יהושע של <b>הברייתא</b>: ״משעת הנחתו״', P('ההזכרה קשורה ל<b>הנחת הלולב</b>, לא לתחילת היום. ולכן מתחילים רק <b>במוסף</b>.'), 'a'),
 step(4, '❓ ״הי בן בתירה?״', P('בברייתא אחרת ר׳ יהודה אומר אותו דין <b>״משום בן בתירה״</b>. אבל <b>ר׳ יהודה בן בתירה</b> אמר שמזכירים כבר <b>ביום השני</b> של החג!'), 'q'),
 step(5, '✅ רב נחמן בר יצחק: ״תהא ב<b>ר׳ יהושע</b> בן בתירה״', chain(('', KIP['young'] + ' לפני שנסמך<br><small>קראו לו בשם אביו:</small><b>״בן בתירה״</b>'), '←', ('gd', '🎓 אחרי שנסמך<br><small>קראו לו בשמו:</small><b>״ר׳ יהושע בן בתירה״</b>')) + P('שני שמות, <b>אותו אדם</b>.', 'margin-top:10px'), 'a'),
